import{_ as a,a0 as i,w as d,s,ao as l,I as p,a1 as t,A as n,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"RHCSA 系列（三）: 如何管理 RHEL7 的用户和組 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（三）: 如何管理 RHEL7 的用户和組 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（三）: 如何管理 RHEL7 的用户和組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（三）: 如何管理 RHEL7 的用户和組 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 03--How to Manage Users and Groups in RHEL 7","title":"RHCSA 系列（三）: 如何管理 RHEL7 的用户和組","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 03--How to Manage Users and Groups in RHEL 7.md","filePath":"[post].md"}'),m={name:"RHCSA Series/RHCSA Series--Part 03--How to Manage Users and Groups in RHEL 7.md"};function u(c,e,h,w,g,f){const r=i("Link");return d(),s("div",null,[e[24]||(e[24]=l(`<h1 id="rhcsa-系列-三-如何管理-rhel7-的用户和組" tabindex="-1">RHCSA 系列（三）: 如何管理 RHEL7 的用户和組 <a class="header-anchor" href="#rhcsa-系列-三-如何管理-rhel7-的用户和組" aria-label="Permalink to “RHCSA 系列（三）: 如何管理 RHEL7 的用户和組”">​</a></h1><p>和管理其它Linux服務器一樣，管理一個 RHEL 7 服務器要求你能夠添加、修改、暫停或刪除用户帳户，並且授予他們執行其分配的任務所需的文件、目錄、其它系統資源所必要的權限。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/User-and-Group-Management-in-Linux.png" alt="User and Group Management in Linux"></p><p><em>RHCSA: 用户和組管理 – Part 3</em></p><p>###管理用户帳户##</p><p>如果想要給RHEL 7 服務器添加賬户，你需要以root用户執行如下兩條命令之一：</p><pre><code># adduser [new_account]
# useradd [new_account]
</code></pre><p>當添加新的用户帳户時，默認會執行下列操作。</p><ul><li>它/她的主目錄就會被創建(一般是&quot;/home/用户名&quot;，除非你特別設置)</li><li>一些隱藏文件 如<code>.bash_logout</code>, <code>.bash_profile</code> 以及 <code>.bashrc</code> 會被複制到用户的主目錄，它們會為用户的回話提供環境變量。你可以進一步查看它們的相關細節。</li><li>會為您的賬號添加一個郵件池目錄。</li><li>會創建一個和用户名同樣的組（LCTT 譯註：除非你給新創建的用户指定了組）。</li></ul><p>用户帳户的全部信息被保存在<code>/etc/passwd</code>文件。這個文件以如下格式保存了每一個系統帳户的所有信息(字段以“:”分割)</p><pre><code>[username]:[x]:[UID]:[GID]:[Comment]:[Home directory]:[Default shell]
</code></pre><ul><li><code>[username]</code> 和<code>[Comment]</code> 其意自明，就是用户名和備註</li><li>第二個‘x’表示帳户的啓用了密碼保護(記錄在<code>/etc/shadow</code>文件)，密碼用於登錄<code>[username]</code></li><li><code>[UID]</code> 和<code>[GID]</code>是整數，它們表明了<code>[username]</code>的用户ID 和所屬的主組ID</li></ul><p>最後。</p><ul><li><code>[Home directory]</code>顯示<code>[username]</code>的主目錄的絕對路徑</li><li><code>[Default shell]</code> 是當用户登錄系統後使用的默認shell</li></ul><p>另外一個你必須要熟悉的重要的文件是存儲組信息的<code>/etc/group</code>。和<code>/etc/passwd</code>類似，也是每行一個記錄，字段由“:”分割</p><pre><code>[Group name]:[Group password]:[GID]:[Group members]
</code></pre><ul><li><code>[Group name]</code> 是組名</li><li>這個組是否使用了密碼 (如果是&quot;x&quot;意味着沒有)</li><li><code>[GID]</code>: 和<code>/etc/passwd</code>中一樣</li><li><code>[Group members]</code>:用户列表，使用“,”隔開。裏面包含組內的所有用户</li></ul><p>添加過帳户後，任何時候你都可以通過 usermod 命令來修改用户賬户信息，基本的語法如下:</p><pre><code># usermod [options] [username]
</code></pre><p>相關閲讀</p>`,20)),p("ul",null,[p("li",null,[t(r,{href:"http://www.tecmint.com/add-users-in-linux/"},{default:n(()=>[...e[0]||(e[0]=[o("15 ‘useradd’ 命令示例",-1)])]),_:1})]),p("li",null,[t(r,{href:"http://www.tecmint.com/usermod-command-examples/"},{default:n(()=>[...e[1]||(e[1]=[o("15 ‘usermod’ 命令示例",-1)])]),_:1})])]),e[25]||(e[25]=l(`<h4 id="示例1-設置帳户的過期時間" tabindex="-1">示例1 : 設置帳户的過期時間 <a class="header-anchor" href="#示例1-設置帳户的過期時間" aria-label="Permalink to “示例1 : 設置帳户的過期時間”">​</a></h4><p>如果你的公司有一些短期使用的帳户或者你要在有限時間內授予訪問，你可以使用 <code>--expiredate</code> 參數 ，後加YYYY-MM-DD 格式的日期。為了查看是否生效，你可以使用如下命令查看</p><pre><code># chage -l [username]
</code></pre><p>帳户更新前後的變動如下圖所示</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Change-User-Account-Information.png" alt="Change User Account Information"></p><p><em>修改用户信息</em></p><h4 id="示例-2-向組內追加用户" tabindex="-1">示例 2: 向組內追加用户 <a class="header-anchor" href="#示例-2-向組內追加用户" aria-label="Permalink to “示例 2: 向組內追加用户”">​</a></h4><p>除了創建用户時的主用户組，一個用户還能被添加到別的組。你需要使用 -aG或 -append -group 選項，後跟逗號分隔的組名。</p><h4 id="示例-3-修改用户主目錄或默認shell" tabindex="-1">示例 3: 修改用户主目錄或默認Shell <a class="header-anchor" href="#示例-3-修改用户主目錄或默認shell" aria-label="Permalink to “示例 3: 修改用户主目錄或默認Shell”">​</a></h4><p>如果因為一些原因，你需要修改默認的用户主目錄(一般為 /home/用户名)，你需要使用 -d 或 -home 參數，後跟絕對路徑來修改主目錄。</p><p>如果有用户想要使用其它的shell來取代默認的bash(比如zsh)。使用 usermod ，並使用 -shell 的參數，後加新的shell的路徑。</p><h4 id="示例-4-展示組內的用户" tabindex="-1">示例 4: 展示組內的用户 <a class="header-anchor" href="#示例-4-展示組內的用户" aria-label="Permalink to “示例 4: 展示組內的用户”">​</a></h4><p>當把用户添加到組中後，你可以使用如下命令驗證屬於哪一個組</p><pre><code># groups [username]
# id [username]
</code></pre><p>下面圖片的演示了示例2到示例4</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Adding-User-to-Supplementary-Group.png" alt="Adding User to Supplementary Group"></p><p><em>添加用户到額外的組</em></p><p>在上面的示例中:</p><pre><code># usermod --append --groups gacanepa,users --home /tmp --shell /bin/sh tecmint
</code></pre><p>如果想要從組內刪除用户，取消 <code>--append</code> 選項，並使用 <code>--groups</code> 和你要用户屬於的組的列表。</p><h4 id="示例-5-通過鎖定密碼來停用帳户" tabindex="-1">示例 5: 通過鎖定密碼來停用帳户 <a class="header-anchor" href="#示例-5-通過鎖定密碼來停用帳户" aria-label="Permalink to “示例 5: 通過鎖定密碼來停用帳户”">​</a></h4><p>如果想要關閉帳户，你可以使用 -l(小寫的L)或 -lock 選項來鎖定用户的密碼。這將會阻止用户登錄。</p><h4 id="示例-6-解鎖密碼" tabindex="-1">示例 6: 解鎖密碼 <a class="header-anchor" href="#示例-6-解鎖密碼" aria-label="Permalink to “示例 6:  解鎖密碼”">​</a></h4><p>當你想要重新啓用帳户讓它可以繼續登錄時，使用 -u 或 –unlock 選項來解鎖用户的密碼，就像示例5 介紹的那樣</p><pre><code># usermod --unlock tecmint
</code></pre><p>下面的圖片展示了示例5和示例6：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Lock-Unlock-User-Account.png" alt="Lock Unlock User Account"></p><p><em>鎖定上鎖用户</em></p><h4 id="示例-7-刪除組和用户" tabindex="-1">示例 7:刪除組和用户 <a class="header-anchor" href="#示例-7-刪除組和用户" aria-label="Permalink to “示例 7:刪除組和用户”">​</a></h4><p>如果要刪除一個組，你需要使用 groupdel ，如果需要刪除用户 你需要使用 userdel (添加 -r 可以刪除主目錄和郵件池的內容)。</p><pre><code># groupdel [group_name]        # 刪除組
# userdel -r [user_name]       # 刪除用户，並刪除主目錄和郵件池
</code></pre><p>如果一些文件屬於該組，刪除組時它們不會也被刪除。但是組擁有者的名字將會被設置為刪除掉的組的GID。</p><h3 id="列舉-設置-並且修改標準-ugo-rwx-權限" tabindex="-1">列舉，設置，並且修改標準 ugo/rwx 權限 <a class="header-anchor" href="#列舉-設置-並且修改標準-ugo-rwx-權限" aria-label="Permalink to “列舉，設置，並且修改標準 ugo/rwx 權限”">​</a></h3>`,33)),p("p",null,[e[3]||(e[3]=o("著名的 ",-1)),t(r,{href:"http://linux.cn/article-5349-1.html"},{default:n(()=>[...e[2]||(e[2]=[o("ls 命令",-1)])]),_:1}),e[4]||(e[4]=o(" 是管理員最好的助手. 當我們使用 -l 參數, 這個工具允許您以長格式（或詳細格式)查看一個目錄中的內容。",-1))]),e[26]||(e[26]=l(`<p>而且，該命令還可以用於單個文件中。無論哪種方式，在“ls”輸出中的前10個字符表示每個文件的屬性。</p><p>這10個字符序列的第一個字符用於表示文件類型：</p><ul><li>– (連字符): 一個標準文件</li><li>d: 一個目錄</li><li>l: 一個符號鏈接</li><li>c: 字符設備（將數據作為字節流，例如終端）</li><li>b: 塊設備（以塊的方式處理數據，例如存儲設備）</li></ul><p>文件屬性的接下來的九個字符，分為三個組，被稱為文件模式，並註明讀（r）、寫（w）、和執行（x）權限授予文件的所有者、文件的所有組、和其它的用户（通常被稱為“世界”）。</p><p>同文件上的讀取權限允許文件被打開和讀取一樣，如果目錄同時有執行權限時，就允許其目錄內容被列出。此外，如果一個文件有執行權限，就允許它作為一個程序運行。</p><p>文件權限是通過chmod命令改變的，它的基本語法如下：</p><pre><code># chmod [new_mode] file
</code></pre><p>new_mode 是一個八進制數或表達式，用於指定新的權限。隨意試試各種權限看看是什麼效果。或者您已經有了一個更好的方式來設置文件的權限，你也可以用你自己的方式自由地試試。</p><p>八進制數可以基於二進制等價計算，可以從所需的文件權限的文件的所有者、所有組、和世界組合成。每種權限都等於2的冪（R = 2^2，W = 2^1，x = 2^0），沒有時即為0。例如：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/File-Permissions.png" alt="File Permissions"></p><p><em>文件權限</em></p><p>在八進制形式下設置文件的權限，如上圖所示</p><pre><code># chmod 744 myfile
</code></pre><p>請用馬上來對比一下我們以前的計算，在更改文件的權限後，我們的實際輸出為：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Long-List-Format.png" alt="Long List Format"></p><p><em>長列表格式</em></p><h4 id="示例-8-尋找777權限的文件" tabindex="-1">示例 8: 尋找777權限的文件 <a class="header-anchor" href="#示例-8-尋找777權限的文件" aria-label="Permalink to “示例 8: 尋找777權限的文件”">​</a></h4><p>出於安全考慮，你應該確保在正常情況下，儘可能避免777權限（任何人可讀、可寫、可執行的文件）。雖然我們會在以後的教程中教你如何更有效地找到您的系統的具有特定權限的全部文件，你現在仍可以組合使用ls 和 grep來獲取這種信息。</p>`,18)),p("p",null,[e[6]||(e[6]=o("在下面的例子，我們會尋找 /etc 目錄下的777權限文件。注意，我們要使用",-1)),t(r,{href:"https://www.linux.cn/article-6155-1.html"},{default:n(()=>[...e[5]||(e[5]=[o("第二章：文件和目錄管理",-1)])]),_:1}),e[7]||(e[7]=o("中講到的管道的知識：",-1))]),e[27]||(e[27]=l(`<pre><code># ls -l /etc | grep rwxrwxrwx
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Find-All-777-Files.png" alt="Find All Files with 777 Permission"></p><p><em>查找所有777權限的文件</em></p><h4 id="示例-9-為所有用户指定特定權限" tabindex="-1">示例 9: 為所有用户指定特定權限 <a class="header-anchor" href="#示例-9-為所有用户指定特定權限" aria-label="Permalink to “示例 9: 為所有用户指定特定權限”">​</a></h4><p>shell腳本，以及一些二進制文件，所有用户都應該有權訪問（不只是其相應的所有者和組），應該有相應的執行權限（我們會討論特殊情況下的問題）：</p><pre><code># chmod a+x script.sh
</code></pre><p><strong>注意</strong>: 我們可以使用表達式設置文件模式，表示用户權限的字母如“u”，組所有者權限的字母“g”，其餘的為“o” ，同時具有所有權限為“a”。權限可以通過<code>+</code> 或 <code>-</code> 來授予和收回。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Set-Execute-Permission-on-File.png" alt="Set Execute Permission on File"></p><p><em>為文件設置執行權限</em></p><p>長目錄列表還用兩列顯示了該文件的所有者和所有組。此功能可作為系統中文件的第一級訪問控制方法：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Check-File-Owner-and-Group.png" alt="Check File Owner and Group"></p><p><em>檢查文件的所有者和所有組</em></p><p>改變文件的所有者，您應該使用chown命令。請注意，您可以在同時或分別更改文件的所有組：</p><pre><code># chown user:group file
</code></pre><p>你可以更改用户或組，或在同時更改兩個屬性，但是不要忘記冒號區分，如果你想要更新其它屬性，讓另外的部分為空：</p><pre><code># chown :group file              # 僅改變所有組
# chown user: file               # 僅改變所有者
</code></pre><h4 id="示例-10-從一個文件複製權限到另一個文件" tabindex="-1">示例 10:從一個文件複製權限到另一個文件#### <a class="header-anchor" href="#示例-10-從一個文件複製權限到另一個文件" aria-label="Permalink to “示例 10:從一個文件複製權限到另一個文件####”">​</a></h4><p>如果你想“克隆”一個文件的所有權到另一個，你可以這樣做，使用–reference參數，如下：</p><pre><code># chown --reference=ref_file file
</code></pre><p>ref_file的所有信息會複製給 file</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Clone-File-Ownership.png" alt="Clone File Ownership"></p><p><em>複製文件屬主信息</em></p><h3 id="設置-setgid-協作目錄" tabindex="-1">設置 SETGID 協作目錄 <a class="header-anchor" href="#設置-setgid-協作目錄" aria-label="Permalink to “設置 SETGID 協作目錄”">​</a></h3><p>假如你需要授予在一個特定的目錄中擁有訪問所有的文件的權限給一個特定的用户組，你有可能需要使用給目錄設置setgid的方法。當setgid設置後，該真實用户的有效GID會變成屬主的GID。</p><p>因此，任何訪問該文件的用户會被授予該文件的屬組的權限。此外，當setgid設置在一個目錄中，新創建的文件繼承組該目錄的組，而且新創建的子目錄也將繼承父目錄的setgid權限。</p><pre><code># chmod g+s [filename]
</code></pre><p>要以八進制形式設置 setgid，需要在基本權限前綴以2。</p><pre><code># chmod 2755 [directory]
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>紮實的用户和組管理知識，以及標準和特殊的 Linux權限管理，通過實踐，可以幫你快速解決 RHEL 7 服務器的文件權限問題。</p>`,30)),p("p",null,[e[9]||(e[9]=o("我向你保證，當你按照本文所概述的步驟和使用系統文檔(在本系列的",-1)),t(r,{href:"http://www.tecmint.com/rhcsa-exam-reviewing-essential-commands-system-documentation/"},{default:n(()=>[...e[8]||(e[8]=[o("第一章 回顧基礎命令及系統文檔",-1)])]),_:1}),e[10]||(e[10]=o("中講到)， 你將掌握基本的系統管理的能力。",-1))]),e[28]||(e[28]=p("p",null,"請隨時使用下面的評論框讓我們知道你是否有任何問題或意見。",-1)),e[29]||(e[29]=p("hr",null,null,-1)),p("p",null,[e[12]||(e[12]=o("via: ",-1)),t(r,{href:"http://www.tecmint.com/rhcsa-exam-manage-users-and-groups/"},{default:n(()=>[...e[11]||(e[11]=[o("http://www.tecmint.com/rhcsa-exam-manage-users-and-groups/",-1)])]),_:1})]),p("p",null,[e[16]||(e[16]=o("作者：",-1)),t(r,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...e[13]||(e[13]=[o("Gabriel Cánepa",-1)])]),_:1}),e[17]||(e[17]=o(" 譯者：",-1)),t(r,{href:"https://github.com/xiqingongzi"},{default:n(()=>[...e[14]||(e[14]=[o("xiqingongzi",-1)])]),_:1}),e[18]||(e[18]=o(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[21]||(e[21]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[19]||(e[19]=[o("LCTT",-1)])]),_:1}),e[22]||(e[22]=o(" 原創翻譯，",-1)),t(r,{href:"https://linux.cn/"},{default:n(()=>[...e[20]||(e[20]=[o("Linux中國",-1)])]),_:1}),e[23]||(e[23]=o(" 榮譽推出",-1))])])}const T=a(m,[["render",u]]);export{S as __pageData,T as default};
